(() => {
  'use strict';
  const api=window.DisasterAPI, app=document.querySelector('#app'), icon=window.icon;
  const params=new URLSearchParams(location.search);
  const s={me:null,ws:null,workspaces:[],route:'dashboard',offset:0,gen:0,cache:{},step:'evaluate',all:false};
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const label=v=>String(v||'').replace(/_/g,' '), money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(n||0));
  const badge=(v,type='')=>`<span class="badge ${esc(type)}">${esc(label(v))}</span>`;
  const initials=name=>String(name||'?').trim().split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();
  const avatar=(name,extra='')=>`<span class="avatar ${esc(extra)}">${esc(initials(name))}</span>`;
  const tags=items=>`<div class="tags">${(items||[]).filter(Boolean).map(x=>`<span class="tag">${esc(label(x))}</span>`).join('')}</div>`;
  const date=v=>v?new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric'}).format(new Date(v)):'Not scheduled';
  const address=o=>[o?.address,o?.city,o?.state,o?.postal_code].filter(Boolean).join(', ');
  const statusType=v=>['completed','paid','active','verified'].includes(v)?'green':['cancelled','urgent','rejected'].includes(v)?'red':'';
  const btn=(text,action,id='',primary=false)=>`<button type="button" class="${primary?'primary':'small-btn'}" ${action==='project-list'?'data-route="projects"':`data-action="${action}" data-id="${esc(id)}"`}>${esc(text)}</button>`;
  const field=(text,name,value='',type='text',required=false)=>`<div class="field"><label>${esc(text)}<input name="${name}" value="${esc(value)}" type="${type}" ${required?'required':''}></label></div>`;
  const select=(text,name,options,value='')=>`<div class="field"><label>${esc(text)}<select name="${name}">${options.map(([id,text])=>`<option value="${esc(id)}" ${String(id)===String(value)?'selected':''}>${esc(text)}</option>`).join('')}</select></label></div>`;
  function head(title,sub='',actions='',eyebrow=''){const safeTitle=String(title).includes('<span class="head-service">')?title:esc(title);return `<div class="page-head"><div>${eyebrow?`<div class="eyebrow">${esc(eyebrow)}</div>`:''}<h1 class="page-title">${safeTitle}</h1>${sub?`<p class="page-subtitle">${esc(sub)}</p>`:''}</div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;}
  const empty=text=>`<section class="panel live-empty">${esc(text)}</section>`;
  const form=(kind,body,id='')=>`<form data-form="${kind}" data-id="${esc(id)}" class="panel live-form">${body}<div class="live-actions"><button class="primary">${kind==='referral'?'Generate referral':kind==='search'?'Search':kind==='workspace'?'Create workspace':'Save'}</button></div><p data-error class="field-error" role="alert"></p></form>`;
  const body=extra=>({workspace_id:s.ws,...extra});
  const call=(name,action,data={})=>api.call(name,action,body(data));
  function toast(text,error=false){document.querySelector('.live-message')?.remove();const el=document.createElement('div');el.className=`live-message ${error?'error':''}`;el.role=error?'alert':'status';el.textContent=text;document.body.append(el);setTimeout(()=>el.remove(),10000);}
  function go(route){s.offset=0;if(location.hash===`#${route}`)render();else location.hash=route;}
  function loginUrl(){const page=location.pathname.split('/').pop()||'index.html';return `login.html?next=${encodeURIComponent(page+location.search+location.hash)}`;}
  const isAdmin=()=>s.me?.profile.is_platform_admin||s.me?.memberships.some(m=>m.workspace_id===s.ws&&m.member_type==='internal'&&m.role==='admin');
  const manages=p=>s.me.profile.is_platform_admin||s.me.memberships.some(m=>m.workspace_id===p.workspace_id&&m.member_type==='internal');
  const navGroups=[
    ['Operational Core',[['dashboard','Dashboard','briefcase'],['projects','Projects','briefcase'],['opportunities','Opportunities','clock'],['quick-referral','Quick Referral','link'],['customers','Customers','users'],['profile','Profile','user']]],
    ['Workspace Admin',[['user-list','User List','users'],['user-management','User Management','user'],['user-tiers','User Tiers','shield'],['core-services','Core Services','shield'],['location','Location','pin'],['workspace','Workspace','building']]]
  ];
  function shell(content){const active=s.route.split('/')[0];return `<div class="shell"><aside class="sidebar" id="main-navigation" aria-label="Main navigation"><div class="brand"><div class="brand-mark">${icon('shield',19)}</div><div><div class="brand-name">Disaster Logic</div><div class="brand-sub">Admin Console</div></div></div><nav class="nav">${navGroups.map(([group,items])=>{const visible=items.filter(n=>s.me.panels.includes(n[0]));return visible.length?`<div class="nav-label">${group}</div>${visible.map(([id,text,ico])=>`<button class="nav-item ${active===id?'active':''}" data-route="${id}">${icon(ico)}<span>${text}</span></button>`).join('')}`:'';}).join('')}</nav><div class="sidebar-footer"><button type="button" class="side-action theme-toggle" data-action="theme" role="switch" aria-checked="${window.AdminTheme.current()==='dark'}">${icon('moon',14)} Dark Mode <span class="toggle" aria-hidden="true"></span></button>${s.me.panels.includes('notifications')?`<button class="side-action" data-route="notifications">${icon('bell',14)} Notifications <span class="notice-dot"></span></button>`:''}<button class="side-action logout" data-action="logout">${icon('logout',14)} Log Out</button></div></aside><button class="sidebar-overlay" data-action="menu" aria-label="Close menu"></button><main class="workspace"><header class="topbar"><button class="mobile-menu" data-action="menu" aria-label="Toggle navigation">${icon('menu',20)}</button><div class="global-search">${icon('search',14)}<input aria-label="Global search" placeholder="Search projects, customer names, or zip codes..."></div><div class="top-actions">${s.me.panels.includes('new-service')?`<button class="primary" data-route="new-service">${icon('plus',14)}<span>New Service Request</span></button>`:''}${s.me.panels.includes('notifications')?`<button class="top-icon" data-route="notifications" aria-label="Notifications">${icon('bell',17)}</button>`:''}</div></header><div class="content" aria-live="polite">${content}</div></main></div>`;}
  function pager(count){return `<div class="table-footer"><span>Showing ${count?s.offset+1:0}–${Math.min(s.offset+25,count)} of ${count} records</span><div class="pagination">${s.offset?btn('Previous','prev'):''}${s.offset+25<count?btn('Next','next'):''}</div></div>`;}
  function url(key,value){const u=new URL(location.href);u.hash='';u.search='';u.searchParams.set(key,value);return u.toString();}
  function auth(){return `<section class="panel auth-card portal-auth"><h2>Sign in to continue</h2><p>Use the secure account page to verify your identity and open this referral.</p><a class="primary" href="${esc(loginUrl())}">Continue to sign in</a></section>`;}
  async function identity(){s.me=await api.call('profile','me',body());const profile=s.me.profile||{},supportsOnboarding=Object.prototype.hasOwnProperty.call(profile,'onboarding_completed_at');if(supportsOnboarding&&!profile.onboarding_completed_at){location.replace('login.html?onboard=1');return false;}s.workspaces=profile.is_platform_admin?await api.call('profile','workspaces'):s.me.memberships.map(m=>({id:m.workspace_id,...m.workspaces,member_type:m.member_type}));const key=`disaster-workspace-${profile.id}`,next=s.workspaces.find(w=>w.id===s.ws)?.id||s.workspaces.find(w=>w.id===localStorage.getItem(key))?.id||s.me.active_workspace_id||s.workspaces.find(w=>w.member_type!=='referral')?.id||s.workspaces[0]?.id||null;s.ws=next;if(s.ws&&s.ws!==s.me.active_workspace_id)s.me=await api.call('profile','me',body());if(s.ws)localStorage.setItem(key,s.ws);return true;}
  const stepFields={evaluate:[['Property condition','condition']],claim:[['Damage cause','cause'],['Water category (1–3)','water_category'],['Property type','property_type']],scope:[['Scope summary','summary']],drying_plan:[['Drying method','method'],['Equipment required','equipment']],contracts:[['Agreement reference','agreement_reference']],work:[['Work progress','progress']],payments:[['Invoice reference','invoice_reference']]};
  async function project(id){const [p,steps]=await Promise.all([api.call('my-projects','get',{id}),api.call('my-projects','steps',{id})]);s.cache.project=p;s.cache.steps=steps;const internal=manages(p),visible=steps.filter(x=>internal||!['claim','contracts','payments'].includes(x.step)).sort((a,b)=>a.workflow_steps.position-b.workflow_steps.position);const step=visible.find(x=>x.step===s.step)||visible[0];s.step=step.step;const next={accepted:['en_route','in_progress'],en_route:['in_progress'],in_progress:['inspection'],inspection:internal?['in_progress','completed']:['in_progress']}[p.status]||[];let html=head(p.customers?.full_name||'Project',p.services?.name)+`<section class="panel live-card"><p>${esc(p.customers?.email)} · ${esc(p.customers?.phone)}</p><p>${esc(p.opportunities?.damage_notes)}</p><p>${badge(p.status)} · ${money(p.scope_estimate)} estimated</p><div class="live-actions">${next.map(x=>btn(`Move to ${label(x)}`,'status',x)).join('')}${internal&&!['completed','cancelled'].includes(p.status)?btn('Cancel project','status','cancelled'):''}${internal?btn('Refer','refer-project',id):''}<button class="small-btn" data-route="projects">Back</button></div></section>`;
    if(internal){const r=await api.sb.from('workspace_members').select('user_id,profiles!workspace_members_user_id_fkey(full_name)').eq('workspace_id',p.workspace_id).eq('member_type','internal').eq('status','active');const members=api.unwrap(r);html+=form('project-details',`<h2>Assignment & Scope</h2>${select('Assigned team member','user_id',members.map(m=>[m.user_id,m.profiles?.full_name||m.user_id]),p.assigned_to)}${field('Scope estimate (USD)','scope_estimate',p.scope_estimate,'number')}${select('Billing type','billing_type',['insurance','self_pay','direct_commercial','hold'].map(x=>[x,label(x)]),p.billing_type)}${isAdmin()?select('Payment record','payment_status',['pending','partial','paid'].map(x=>[x,label(x)]),p.payment_status):''}`,id);}
    html+=`<section class="panel live-form"><h2>Project Workflow</h2><div class="live-tabs">${visible.map(x=>`<button class="small-btn ${x.step===step.step?'active':''}" data-action="step" data-id="${x.step}">${x.workflow_steps.position}. ${esc(x.workflow_steps.name)} ${x.completed_at?'✓':''}</button>`).join('')}</div></section>`+form('step',`<h3>${esc(step.workflow_steps.name)}</h3>${(stepFields[step.step]||[]).map(([title,name])=>field(title,name,step.data[name])).join('')}<div class="field"><label>Notes<textarea name="notes">${esc(step.data.notes)}</textarea></label></div><label><input type="checkbox" name="complete" ${step.completed_at?'checked':''}> Mark this step complete</label>`,id)+head('Project Referrals')+p.referrals.map(i=>`<section class="panel live-card">${esc(i.invitee_name)} ${badge(i.target)} ${badge(i.status)} · ${money(i.payout_amount)}</section>`).join('');
    const activity=api.unwrap(await api.sb.from('project_activity').select('action,details,created_at').eq('project_id',id).order('created_at',{ascending:false}).limit(20));return html+head('Activity')+`<section class="panel live-card">${activity.map(a=>`<p>${new Date(a.created_at).toLocaleString()} · ${esc(label(a.action))}${a.details.from?` · ${esc(a.details.from)} → ${esc(a.details.to)}`:''}${a.details.step?` · ${esc(label(a.details.step))}`:''}</p>`).join('')}</section>`;}
  async function customer(id){const c=id==='new'?{}:await call('customers','get',{id});return head(c.full_name||'Add Customer')+form('customer',field('Full name','full_name',c.full_name,'text',true)+field('Email','email',c.email,'email')+field('Phone','phone',c.phone,'tel')+select('Property type','property_type',[['','Not specified'],['residential','Residential'],['commercial','Commercial']],c.property_type),c.id)+(c.projects||[]).map(p=>`<section class="panel live-card">${esc(p.services?.name)} ${badge(p.status)} · ${money(p.scope_estimate)} ${btn('Open Project','project',p.id)}</section>`).join('');}
  async function notifications(){const items=await call('profile','notifications');return head('Notifications')+btn('Mark all as read','mark-read')+'<br><br>'+items.map(n=>`<section class="panel live-card"><h2>${esc(n.title)} ${!n.read_at?badge('Unread'):''}</h2><p>${esc(n.body)}</p>${n.project_id?btn('Open Project','project',n.project_id):n.opportunity_id?btn('View Opportunity','opportunity',n.opportunity_id):''}</section>`).join('');}
  async function workspace(){const w=s.workspaces.find(w=>w.id===s.ws),services=api.unwrap(await api.sb.from('services').select('id,name').order('sort_order'));return head('Workspace','Each company has its own team, services, coverage, and public booking link.')+(w?`<section class="panel live-card"><h2>${esc(w.name)}</h2><p>${esc(w.timezone)}</p><p class="mono">${esc(url('booking',w.public_key))}</p>${btn('Copy booking link','copy-booking',w.public_key)}</section>`:empty('Create the first workspace.'))+(s.me.profile.is_platform_admin?form('workspace',`<h2>Create Workspace</h2>${field('Company name','name','','text',true)}${field('Slug (lowercase, hyphens)','slug','','text',true)}${field('Admin email (existing account)','admin_email','','email',true)}${field('Time zone','timezone','America/Chicago','text',true)}<div class="field"><label>Initial services</label>${services.map(x=>`<label><input type="checkbox" name="service_ids" value="${x.id}"> ${esc(x.name)}</label>`).join('')}</div>`):'');}
  async function locations(){const r=await call('profile','locations');return head('Service Areas','ZIP/postal codes determine eligibility for shared jobs.')+r.map(x=>`<section class="panel live-card"><h2>${esc(x.name)}</h2><p>${esc(x.postal_codes.join(', '))}</p></section>`).join('')+form('location',field('Area name','name','','text',true)+field('ZIP/postal codes (comma separated)','postal_codes','','text',true));}
  async function booking(key){const f=key?await api.rpc('get_booking_form',{p_public_key:key}):await call('opportunities','form');if(!f)throw new Error('Booking link is invalid or inactive.');if(!f.services.length)return empty('This workspace has not enabled booking services.');window.BookingView.setServices(f.services);window.BookingView.setSubmitHandler(async payload=>{const r=await api.submitBooking(key||f.public_key,payload);toast(`Booking received: ${r.opportunity_id}`);});return `<div class="eyebrow">${esc(f.workspace.name)} · ${esc(f.workspace.timezone)}</div>`+window.BookingView.render();}
  async function opportunity(id){
    const o=await api.call('opportunities','get',{id});
    const files=await Promise.all((o.opportunity_media||[]).map(async f=>({...f,url:await api.mediaUrl(f.storage_path)})));
    const attachments=files.length?files.map(f=>`<div class="attachment">${f.mime_type.startsWith('image/')?`<img class="damage-photo" src="${esc(f.url)}" alt="${esc(f.file_name)}">`:`<span class="round-icon">${icon('briefcase',16)}</span>`}<div><b>${esc(f.file_name)}</b><div class="person-sub">${esc(f.mime_type)}</div><a href="${esc(f.url)}" target="_blank" rel="noopener">Open attachment</a></div>${badge('Verified','green')}</div>`).join(''):'<div class="note-box">No damage attachments were supplied.</div>';
    return `${head(`${esc(o.customers?.full_name||'Opportunity')} <span class="head-service">· ${esc(o.services?.name||'Service request')}</span>`,'',`<button class="secondary" data-route="opportunities">Back to Opportunities</button>${['new','offered'].includes(o.status)?btn('Accept Opportunity','accept',id,true):''}`)}<div class="panel referral-banner"><div class="round-icon">${icon('briefcase',16)}</div><div class="referral-copy"><b>Customer intake received</b><div>Review the intake details before accepting and assigning resources.</div></div>${badge(o.status,statusType(o.status))}</div><div class="detail-layout"><div><section class="panel step-card"><div class="step-head"><span class="step-number">1</span>Location & Coverage <span class="verified">Intake detail</span></div><div class="step-body"><div class="coverage-grid"><div class="mini-box"><div class="mini-label">Postal Code / Area</div><div class="mini-value detail-postal">${esc(o.postal_code||'—')}</div><div class="person-sub">${esc([o.city,o.state].filter(Boolean).join(', '))}</div></div><div class="mini-box"><div class="mini-label">Full Address</div><div class="mini-value">${esc(address(o)||'Not supplied')}</div></div></div></div></section><section class="panel step-card"><div class="step-head"><span class="step-number">3</span>Customer Details & Damage Scope <span class="verified">Contact detail</span></div><div class="step-body"><div class="contact-grid"><div class="mini-box"><div class="mini-label">Full Name</div><div class="mini-value">${esc(o.customers?.full_name||'—')}</div></div><div class="mini-box"><div class="mini-label">Phone Number</div><div class="mini-value">${esc(o.customers?.phone||'—')}</div></div><div class="mini-box"><div class="mini-label">Email Address</div><div class="mini-value">${esc(o.customers?.email||'—')}</div></div></div><div class="info-label detail-section-label">Damage Notes</div><div class="note-box">${esc(o.damage_notes||'No damage notes supplied.')}</div><div class="info-label detail-section-label">Attached Damage Proof</div>${attachments}</div></section></div><div><section class="panel step-card"><div class="step-head"><span class="step-number">2</span>Selected Service Type <span class="verified">Service match</span></div><div class="step-body"><div class="service-choice"><div class="service-icon">${icon('briefcase',18)}</div><div><b>${esc(o.services?.name||'Service request')}</b><div class="service-priority">${esc(label(o.priority||'normal'))} priority</div></div></div>${tags([o.visibility,o.status])}</div></section><section class="panel step-card"><div class="step-head"><span class="step-number">4</span>Dispatch Priority & Availability <span class="verified">Schedule</span></div><div class="dispatch-card"><div class="dispatch-grid"><div class="mini-box"><div class="mini-label">Target Service Date</div><div class="mini-value">${esc(date(o.preferred_date))}</div></div><div class="mini-box"><div class="mini-label">Requested Arrival Window</div><div class="mini-value">${esc(o.preferred_window||'Not selected')}</div></div></div>${['new','offered'].includes(o.status)?`<button class="primary accept-wide" data-action="accept" data-id="${esc(id)}">${icon('check',13)} Accept & Create Project</button>`:''}<button class="small-btn accept-wide" data-action="refer-opportunity" data-id="${esc(id)}">Refer to a Partner</button></div></section></div></div>`;
  }

  async function profile(){
    const p=s.me.profile;
    const internal=!!s.ws&&s.me.panels.includes('opportunities');
    const [services,locations,days]=await Promise.all([
      internal?call('profile','services'):Promise.resolve({services:[],selected:[]}),
      internal?call('profile','locations'):Promise.resolve([]),
      internal?call('profile','get_availability'):Promise.resolve([])
    ]);
    const workspace=s.workspaces.find(w=>w.id===s.ws),membership=s.me.memberships.find(m=>m.workspace_id===s.ws);
    const serviceCount=services.selected?.length||0,hasAvailability=days.some(d=>d.available_9_5||d.available_after_hours);
    const row=(ico,title,sub,status,tone='',attrs='')=>`<button type="button" class="profile-setting" ${attrs}><span class="setting-icon">${icon(ico,14)}</span><span class="setting-copy"><b>${esc(title)}</b><small>${esc(sub)}</small></span>${badge(status,tone)}${icon('chevron',12)}</button>`;
    const contactComplete=!!(p.full_name&&p.email),connected=workspace?.name||membership?.workspaces?.name||'Disaster Logic';
    let editor='';
    if(s.cache.profileSection==='contact')editor=`<section class="profile-editor">${form('profile',`<div class="section-title">Contact Information</div>${field('Full name','full_name',p.full_name,'text',true)}${field('Phone','phone',p.phone,'tel')}${field('Avatar URL (HTTPS)','avatar_url',p.avatar_url,'url')}`)}</section>`;
    if(s.cache.profileSection==='availability')editor=`<section class="profile-editor">${form('availability',`<div class="section-title">Availability</div><p class="page-subtitle">Set the hours this account can receive dispatches.</p>${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'].map((name,i)=>{const d=days.find(x=>x.day_of_week===i);return `<div class="availability-row"><b>${name}</b><label><input type="checkbox" name="day-${i}" ${d?.available_9_5?'checked':''}> 9–5</label><label><input type="checkbox" name="after-${i}" ${d?.available_after_hours?'checked':''}> After hours</label></div>`;}).join('')}`)}</section>`;
    return `${head('Profile workspace',"Editing applies to this user's selected workspace profile.")}<section class="panel profile-identity">${p.avatar_url?`<img class="profile-avatar" src="${esc(p.avatar_url)}" alt="">`:avatar(p.full_name||p.email)}<div><span class="profile-identity-label">User profile</span><h2>${esc(p.full_name||'Account profile')}</h2><div class="person-sub">${esc(p.email)}</div><span class="profile-connected">${icon('link',10)} Connected to user: ${esc(connected)}</span></div></section><div class="profile-columns"><div class="profile-column"><section class="panel profile-group"><div class="section-title">Work Profile</div>${row('shield','Services & credentials',serviceCount?`${serviceCount} core service${serviceCount===1?'':'s'} selected`:'Services you provide and credentials for each one.',serviceCount?'Configured':'Action needed',serviceCount?'green':'amber',s.me.panels.includes('core-services')?'data-route="core-services"':'disabled')}${row('pin','Service area',locations.length?`${locations.length} configured service location${locations.length===1?'':'s'}`:'Your base location and covered service locations.',locations.length?'Configured':'Action needed',locations.length?'green':'amber',s.me.panels.includes('location')?'data-route="location"':'disabled')}${row('calendar','Availability','Scheduling availability and after-hours coverage.',hasAvailability?'Configured':'Unassigned',hasAvailability?'green':'amber',internal?'data-action="profile-section" data-id="availability"':'disabled')}</section><section class="panel profile-group"><div class="section-title">Network</div>${row('link','Referrals','Referral links and the users you have referred.',s.me.panels.includes('quick-referral')?'Active network':'Not active','amber',s.me.panels.includes('quick-referral')?'data-route="quick-referral"':'disabled')}${row('network','Connections','View and manage your account relationships.',`${s.me.memberships.length} connection${s.me.memberships.length===1?'':'s'}`,'',s.me.panels.includes('user-list')?'data-route="user-list"':'disabled')}</section></div><div class="profile-column"><section class="panel profile-group"><div class="section-title">Account</div>${row('id-card','Contact information','Name, email, phone, address, and personal details.',contactComplete?'Complete':'Action needed',contactComplete?'green':'amber','data-action="profile-section" data-id="contact"')}</section><section class="panel profile-group"><div class="section-title">Financial Settings</div>${row('briefcase','Payout settings','Stripe setup and accounts used to receive payouts.','Action needed','amber','disabled')}</section></div></div>${editor}`;
  }

  async function customers(){
    const r=await call('customers','list',{offset:s.offset,search:s.cache.search});
    const rows=r.items.map(c=>{const latest=[...(c.projects||[])].sort((a,b)=>new Date(b.created_at)-new Date(a.created_at))[0];const total=(c.projects||[]).reduce((n,p)=>n+Number(p.scope_estimate||0),0);return `<tr><td><div class="person-cell">${avatar(c.full_name)}<div><div class="person-main">${esc(c.full_name)}</div><div class="person-sub">${esc(c.email||c.phone||'No contact details')}</div></div></div></td><td>${badge(c.property_type||'Not specified')}</td><td><div class="job-main">${esc(latest?.services?.name||'No projects')}</div><div class="person-sub">${latest?date(latest.created_at):'—'}</div></td><td><b>${money(total)}</b></td><td>${latest?badge(latest.payment_status,statusType(latest.payment_status)):'—'}</td><td><button class="action-link" data-action="customer" data-id="${esc(c.id)}">Details ›</button></td></tr>`;}).join('');
    return `${head('Customers','View and manage customers, their projects, and billing history.',`<button class="primary" data-action="customer-new">${icon('plus',12)} Add Customer</button>`)}<form data-form="search" class="panel search-strip">${icon('search',14)}<input name="search" value="${esc(s.cache.search||'')}" placeholder="Search customer name, email, phone, or address..."><button class="small-btn">${icon('search',11)} Search</button><p data-error class="field-error"></p></form><section class="panel customer-table">${rows?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Customer</th><th>Type</th><th>Latest Project</th><th>Total Estimate</th><th>Payment</th><th>Action</th></tr></thead><tbody>${rows}</tbody></table></div>${pager(r.count)}`:empty('No matching customers.')}</section>`;
  }

  async function members(tiers){
    const [people,sv]=await Promise.all([call('profile','members'),tiers?call('profile','services'):Promise.resolve(null)]);s.cache.people=people;
    if(tiers){const enabled=sv.services.filter(x=>sv.selected.some(v=>v.service_id===x.id));const rows=people.filter(m=>m.member_type==='internal').map(m=>`<article class="panel user-row">${avatar(m.profiles?.full_name||m.profiles?.email)}<div class="user-meta"><b>${esc(m.profiles?.full_name||m.profiles?.email)}</b>${badge(m.job_title||m.role)}${badge(m.status,statusType(m.status))}</div>${form('tiers',enabled.map(x=>{const v=m.member_services.find(item=>item.service_id===x.id);return `<div class="tier-control">${select(x.name,`tier-${x.id}`,[['','Not assigned'],[1,'Tier 1'],[2,'Tier 2'],[3,'Tier 3']],v?.tier??'')}${select('Verification',`verification-${x.id}`,['unverified','pending','verified','rejected'].map(value=>[value,label(value)]),v?.verification_status)}</div>`;}).join(''),m.user_id)}</article>`).join('');return `${head('User Tiers','Set service verification and dispatch priority for internal team members.',`<span class="badge">${people.length} total</span>`)}<div class="users-list">${rows||empty('No internal team members yet.')}</div>`;}
    const workspaceName=s.workspaces.find(w=>w.id===s.ws)?.name||'Workspace';
    const rows=people.map(m=>{const name=m.profiles?.full_name||m.profiles?.email||'Account';const searchable=[name,m.profiles?.email,m.profiles?.phone,m.job_title,m.role].filter(Boolean).join(' ').toLowerCase();return `<article class="panel user-row" data-user-row data-search="${esc(searchable)}" data-role="${esc(m.role||'')}" data-status="${esc(m.status||'')}">${avatar(name)}<span class="online-dot ${m.status==='active'?'online':'offline'}"></span><div class="user-meta"><b>${esc(name)}</b>${badge(m.job_title||label(m.role))}${m.available_for_scheduling?badge('Available','green'):''}</div><div class="user-contact"><span>${icon('mail',11)} ${esc(m.profiles?.email||'No email')}</span>${m.profiles?.phone?`<span>${icon('phone',11)} ${esc(m.profiles.phone)}</span>`:''}<span>${icon('building',11)} ${esc(workspaceName)}</span></div><button class="small-btn" data-route="user-management/${esc(m.user_id)}">Open Profile ${icon('chevron',10)}</button></article>`;}).join('');
    const roleOptions=[...new Set(people.map(m=>m.role).filter(Boolean))].map(value=>`<option value="${esc(value)}">${esc(label(value))}</option>`).join('');
    const statusOptions=[...new Set(people.map(m=>m.status).filter(Boolean))].map(value=>`<option value="${esc(value)}">${esc(label(value))}</option>`).join('');
    const invite=s.cache.showInvite?form('member','<h2>Invite Existing Account</h2><div class="split">'+field('Email','email','','email',true)+select('Role','role',[['member','Internal user'],['admin','Workspace admin']])+'</div>'+field('Job title','job_title')):'';
    return `${head(`Users & Personnel`, 'Manage workspace members, field technicians, partner contractors, and permission roles.',`<span class="badge">${people.length} total</span><button class="small-btn" data-action="export-users">${icon('download',12)} Export CSV</button><button class="primary" data-action="toggle-member-invite">${icon('plus',12)} Invite User</button>`)}${invite}<div class="panel search-strip user-filters">${icon('search',14)}<input data-user-search placeholder="Search by name, role, email, or phone number..."><select data-user-role aria-label="Filter by role"><option value="">All Roles</option>${roleOptions}</select><select data-user-status aria-label="Filter by status"><option value="">All Statuses</option>${statusOptions}</select><span class="workspace-team">${icon('users',11)} ${esc(workspaceName)}</span></div><div class="users-list">${rows||empty('No workspace members yet.')}</div><div class="table-footer"><span data-user-count>Showing ${people.length} workspace members</span></div>`;
  }

  async function userManagement(id){
    const [people,sv]=await Promise.all([call('profile','members'),call('profile','services')]);s.cache.people=people;
    if(!id){const rows=people.map(m=>{const name=m.profiles?.full_name||m.profiles?.email||'Account';return `<article class="panel manage-row">${avatar(name)}<div><b>${esc(name)}</b><div class="tiny">${esc(m.profiles?.email||'')}</div></div>${badge(m.available_for_scheduling?'Available':'Unavailable',m.available_for_scheduling?'green':'')}<button class="manage-options" data-route="user-management/${esc(m.user_id)}">Open Profile ${icon('chevron',9)}</button><div class="manage-options">Available for matching ${m.available_for_scheduling?'☑':'☐'}</div></article>`;}).join('');return `${head('User Management','Manage user visibility, access, and project permissions.',`<div class="segmented"><span class="active">Service Provider</span><span>Referral</span><span>Internal</span></div>`)}<div class="manage-list">${rows||empty('No workspace members yet.')}</div>`;}
    const member=people.find(m=>m.user_id===id);if(!member)return empty('This user is not part of the active workspace.');
    const name=member.profiles?.full_name||member.profiles?.email||'Account';const enabled=sv.services.filter(x=>sv.selected.some(v=>v.service_id===x.id));
    const setting=(ico,title,sub,value)=>`<div class="setting-row"><span class="setting-icon">${icon(ico,14)}</span><div class="setting-copy"><b>${esc(title)}</b><div>${esc(sub)}</div></div>${badge(value)}</div>`;
    return `${head('Profile workspace','Edit this user’s workspace profile and permissions.',`<button class="small-btn" data-route="user-management">Back to users</button>`)}<section class="panel user-detail-head">${avatar(name)}<div><h2>${esc(name)}</h2><div class="person-sub">${esc(member.profiles?.email||'')}</div><div class="profile-badges">${badge(member.member_type)} ${badge(member.role)} ${badge(member.status,statusType(member.status))}</div></div></section><div class="detail-sections"><section class="panel section-card"><div class="section-title">Work Profile</div>${setting('briefcase','Services & credentials',`${enabled.length} workspace services available`,member.member_services?.length?'Configured':'Action needed')}${setting('pin','Service area',member.job_title||'No job title assigned',member.available_for_scheduling?'Available':'Unavailable')}${setting('clock','Availability','Controls matching and dispatch visibility',member.available_for_scheduling?'Enabled':'Disabled')}</section><section class="panel section-card"><div class="section-title">Account</div>${form('member-settings',select('Role','role',member.member_type==='referral'?[['member','Referral member']]:[['member','Internal user'],['admin','Workspace admin']],member.role)+select('Access status','status',[['active','Active'],['disabled','Disabled'],['invited','Invited']],member.status)+`<label><input type="checkbox" name="available" ${member.available_for_scheduling?'checked':''}> Available for dispatch and matching</label>`,member.user_id)}</section><section class="panel section-card"><div class="section-title">Network</div>${setting('link','Referrals','Referral routing and partner activity',member.member_type==='referral'?'Active':'Workspace')}${setting('users','Connections','Workspace team membership',label(member.status))}</section><section class="panel section-card"><div class="section-title">Service Tiers</div>${form('tiers',enabled.map(x=>{const v=member.member_services.find(item=>item.service_id===x.id);return `<div class="tier-control">${select(x.name,`tier-${x.id}`,[['','Not assigned'],[1,'Tier 1'],[2,'Tier 2'],[3,'Tier 3']],v?.tier??'')}${select('Verification',`verification-${x.id}`,['unverified','pending','verified','rejected'].map(value=>[value,label(value)]),v?.verification_status)}</div>`;}).join(''),member.user_id)}</section></div>`;
  }

  async function services(){
    const r=await call('profile','services'),workspaceName=s.workspaces.find(w=>w.id===s.ws)?.name||'Workspace',selected=new Set(r.selected.map(v=>v.service_id));
    return `${head('Core Services','Choose the global service types this workspace treats as core services.',`<button class="primary" type="submit" form="core-services-form">${icon('check',12)} Save Core Services</button>`)}<section class="panel service-header-card"><div class="global-search service-search">${icon('search',14)}<input data-service-search placeholder="Search service types..."></div><div class="service-summary">Workspace: <b>${esc(workspaceName)}</b><span>·</span><b>${selected.size} selected</b><span>·</span><span>Saved</span></div></section><form id="core-services-form" data-form="services" class="panel core-services-grid"><div class="service-grid">${r.services.map(x=>{const checked=selected.has(x.id),name=x.name||'',warning=/fire.*smoke/i.test(name)?['Priority Triage','red']:/drain|reconstruction|water clean|biohazard/i.test(name)?['Verification required','']:null;return `<label class="service-card ${checked?'selected':''}" data-service-card data-search="${esc(`${name} ${x.description||''}`.toLowerCase())}"><input type="checkbox" name="service_ids" value="${esc(x.id)}" ${checked?'checked':''}><span class="service-check">${checked?icon('check',11):''}</span><h3>${esc(name)}</h3><p>${esc(x.description||'Available for workspace intake and dispatch.')}</p>${warning?`<span class="service-warning ${warning[1]}">${warning[0]}</span>`:''}</label>`;}).join('')}</div><p data-error class="field-error" role="alert"></p></form>`;
  }

  async function referral(){
    const [p,r,contacts,ws]=await Promise.all([call('my-projects','list',{mine:false,limit:100}),call('quick-referral','list',{offset:s.offset}),call('quick-referral','contacts'),call('quick-referral','workspaces')]);s.cache.contacts=contacts;
    const pending=s.cache.opportunity?await api.call('opportunities','get',{id:s.cache.opportunity}):null;
    const choices=p.items.filter(x=>!['completed','cancelled'].includes(x.status)).map(x=>[x.id,`${x.customers?.full_name} — ${x.services?.name}`]);
    const referralForm=pending||choices.length?`<form data-form="referral" class="panel form-card">${pending?`<div class="form-title">Refer ${esc(pending.customers?.full_name)}</div><input type="hidden" name="opportunity_id" value="${esc(pending.id)}">`:`<div class="form-title">Create & Dispatch Referral</div>${select('Project to refer','project_id',choices,s.cache.referralProject)}`}<div class="form-step"><span class="step-number">1</span><b>Select referral destination</b></div><div class="tabs">${[['individual','Assign to Individual'],['workspace','Assign to Workspace'],['opportunities','Show in Opportunities']].map(([v,t],i)=>`<button type="button" class="tab ${!i?'active':''}" data-action="target" data-id="${v}">${t}</button>`).join('')}</div><input type="hidden" name="target" value="individual"><div data-target="individual">${select('Previous contact','contact',[['','Add a new referral'],...contacts.map((c,i)=>[i,c.invitee_name])])}<div class="split">${field('Contractor full name','name')}${field('Email','email','','email')}</div><div class="split">${field('Phone','phone','','tel')}${field('Agreed payout (USD)','payout_amount',0,'number')}</div></div><div data-target="workspace" hidden>${select('Receiving workspace','target_workspace_id',[['','Select workspace'],...ws.filter(w=>w.id!==s.ws).map(w=>[w.id,w.name])])}${field('Agreed payout (USD)','payout_amount',0,'number')}</div><div data-target="opportunities" hidden><div class="estimate">Matching providers will see this referral on their Opportunities board.</div>${field('Agreed payout (USD)','payout_amount',0,'number')}</div><div class="field"><label>Special instructions<textarea name="instructions" maxlength="2000"></textarea></label></div><div class="live-actions"><button class="primary">Generate Referral</button></div><p data-error class="field-error"></p></form>`:empty('Accept a booking first, then refer its project.');
    const link=`<section class="panel link-card"><div class="form-title">Generated Link & Dispatch Panel</div><p class="page-subtitle">The recipient can securely review and claim the project.</p>${s.cache.invite?s.cache.invite.target==='opportunities'?'<div class="estimate">This referral is live on eligible Opportunities boards.</div>':`<div class="generated-link"><input readonly value="${esc(url('ref',s.cache.invite.token))}"><button class="small-btn" data-action="copy-referral" data-id="${esc(s.cache.invite.token)}">${icon('copy',12)} Copy</button></div><div class="link-status">Account ${esc(s.cache.invite.account_status)}. ${esc(s.cache.invite.account_warning||'')}</div>`:'<div class="estimate">Generate a referral to create its secure URL.</div>'}</section>`;
    const rows=r.items.map(i=>`<tr><td><b>${esc(i.projects?.customers?.full_name||'Project')}</b><div class="tiny">${esc(i.projects?.services?.name||'')}</div></td><td>${esc(i.invitee_name||label(i.target))}</td><td><b>${money(i.payout_amount)}</b></td><td>${badge(i.status,statusType(i.status))}</td><td><div class="op-actions">${i.target!=='opportunities'?btn('Copy','copy-referral',i.token):''}${['draft','link_sent','viewed'].includes(i.status)?btn('Revoke','revoke',i.id):''}</div></td></tr>`).join('');
    return `${head('Quick Referral','Assign work to an external contractor or partner using a secure, tracked invitation.')}<div class="referral-grid">${referralForm}${link}</div><section class="panel referral-table">${rows?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Project & Customer</th><th>Referral Recipient</th><th>Agreed Payout</th><th>Status</th><th>Actions</th></tr></thead><tbody>${rows}</tbody></table></div>${pager(r.count)}`:empty('No referral records yet.')}</section>`;
  }

  async function dashboard(){
    if(s.me.profile.account_type==='referral'&&!s.ws)return head('Referral Partner','Send qualified leads and track projects connected to your referrals.')+`<div class="live-grid"><section class="panel live-card"><h2>My Projects</h2><p>Claimed referral projects and their current status appear here.</p>${btn('View projects','project-list','',true)}</section><section class="panel live-card"><h2>My Profile</h2><p>Keep your contact and trade details current.</p><button class="small-btn" data-route="profile">Open profile</button></section></div>`;
    const [r,jobs]=await Promise.all([call('opportunities','stats'),call('my-projects','list',{mine:false,limit:5})]);
    const rows=jobs.items.map(p=>`<tr><td><div class="person-cell">${avatar(p.customers?.full_name)}<div><div class="person-main">${esc(p.customers?.full_name||'Customer')}</div><div class="person-sub">${esc(address(p.opportunities))}</div></div></div></td><td><div class="job-main">${esc(p.services?.name||'Service')}</div><div class="person-sub text-clamp">${esc(p.opportunities?.damage_notes||'No scope notes')}</div></td><td><div class="person-main">${esc(p.project_members?.[0]?.profiles?.full_name||'Unassigned')}</div><div class="person-sub">${esc(label(p.project_members?.[0]?.role||''))}</div></td><td><span class="status ${statusType(p.status)}">${esc(label(p.status))}</span></td><td class="money">${money(p.scope_estimate)}</td></tr>`).join('');
    return `<div class="stats"><section class="panel stat"><div class="stat-label">Pending</div><div class="stat-value">${r.open_opportunities||0} <span class="tiny">Queued Jobs</span></div><div class="stat-meta"><span>Est. Pipeline Value</span><b>${money(r.pipeline_value)}</b></div><div class="stat-icon">${icon('briefcase',18)}</div></section><section class="panel stat"><div class="stat-label">Completed</div><div class="stat-value green">${r.completed_projects||0}</div><div class="stat-meta"><span>Completed Scope</span><b>${money(r.completed_value)}</b></div><div class="stat-icon">${icon('check',18)}</div></section><section class="panel stat"><div class="stat-label">Active Projects</div><div class="stat-value blue">${r.active_projects||0}</div><div class="stat-meta"><span>Total Active Portfolio</span><b>${money(r.pipeline_value)}</b></div><div class="stat-icon">${icon('briefcase',18)}</div></section></div><div class="panel referral-banner"><div class="round-icon">${icon('link',17)}</div><div class="referral-copy"><b>Referral Dispatch & Partner Network</b><div>Dispatch partner assignments with secure referral links and live status tracking.</div></div><button class="primary" data-route="quick-referral">${icon('plus',13)} Generate & Send Referral</button></div><section class="panel"><div class="panel-titlebar"><div class="title-accent"></div><div><h2>Team Work Operations</h2><p>Active field dispatches and recently completed jobs</p></div><div class="panel-controls"><button class="small-btn" data-route="projects">View all projects</button></div></div>${rows?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Client & Location</th><th>Scope of Work</th><th>Assigned Team / Crew</th><th>Status</th><th style="text-align:right">Amount / Estimate</th></tr></thead><tbody>${rows}</tbody></table></div>${pager(jobs.count)}`:empty('No projects yet. New work will appear here after an opportunity is accepted.')}</section>`;
  }

  async function opportunities(){
    const [r,board]=await Promise.all([call('opportunities','list',{offset:s.offset}),call('opportunities','referral_board')]);
    const incoming=board.filter(i=>i.eligible_workspaces.includes(s.ws));
    const cards=await Promise.all(r.items.map(async o=>{const media=o.opportunity_media?.[0];let image='';if(media){try{image=await api.mediaUrl(media.storage_path);}catch{image='';}}return `<article class="panel op-card"><div class="op-photo ${image?'':'op-photo-empty'}"${image?` style="background-image:url('${esc(image)}')"`:''}>${image?'':icon('briefcase',30)}<span class="photo-date">${date(o.created_at)}</span><div class="photo-meta"><span>LEAD<br><b>${esc(String(o.postal_code||'—'))}</b></span><span>${esc(label(o.priority||'normal'))}</span></div></div><div class="op-body"><div class="op-kicker">Opportunity ${o.priority==='urgent'?badge('Urgent','red'):''}</div><h2 class="op-name">${esc(o.customers?.full_name||'Customer')}</h2><div class="address">${icon('pin',12)} ${esc(address(o)||'Address not supplied')}</div><div class="op-info"><div class="info-box"><div class="info-label">Job Type</div><div class="info-value">${esc(o.services?.name||'Service request')}</div><div class="info-sub text-clamp">${esc(o.damage_notes||'No damage notes supplied.')}</div></div><div class="info-box"><div class="info-label">Schedule</div><div class="info-value">${icon('calendar',12)} ${esc(date(o.preferred_date))}</div><div class="info-sub">${esc(o.preferred_window||'Window not selected')}</div></div></div><div class="op-footer">${tags([o.visibility,o.status])}<div class="op-actions">${btn('View','opportunity',o.id)}${btn('Accept','accept',o.id,true)}${btn('Refer','refer-opportunity',o.id)}</div></div></div></article>`;}));
    const referred=incoming.length?`${head('Incoming Referrals','Shared jobs matching this workspace’s services and coverage.')}<div class="opportunity-list">${incoming.map(i=>`<article class="panel project-card"><div class="project-top"><div><div class="op-kicker">Incoming referral</div><h3>${esc(i.service)}</h3><div class="address">${icon('pin',11)} ${esc([i.city,i.state,i.postal_code].filter(Boolean).join(', '))}</div></div><div class="project-type">From ${esc(i.from_workspace)}<br><b>${money(i.payout_amount)}</b></div></div><p>${esc(i.special_instructions||'No special instructions.')}</p><div class="project-action">${btn('Accept Referral','accept-listing',i.id,true)}</div></article>`).join('')}</div>`:'';
    return `${head('Opportunities','Review new jobs that match your coverage, service type, and availability.')}<div class="toolbar"><span class="chip">${icon('clock',12)} Live intake</span><span class="chip">${r.count} available</span>${incoming.length?`<span class="chip">${incoming.length} referred</span>`:''}</div><div class="panel search-strip">${icon('search',14)}<input aria-label="Search opportunities" placeholder="Search by customer name"><button class="strip-action">${icon('filter',12)} Filter</button></div><div class="opportunity-list">${cards.join('')}</div>${!r.count?empty('No available booking opportunities.'):pager(r.count)}${referred}`;
  }

  async function projects(){
    const r=await call('my-projects','list',{offset:s.offset,mine:!s.all});
    return `${head('Accepted Projects','Coordinate active restoration work, assignments, schedules, and project status.')}<div class="panel search-strip">${icon('search',14)}<input placeholder="Search by customer name, address, or ID..."><div class="project-filters">${btn(s.all?'Show my assignments':'Show all workspace projects','toggle-projects')}</div></div>${r.items.map(p=>`<article class="panel project-card"><div class="project-top"><div><div class="op-kicker">Accepted Project</div><h3>${esc(p.customers?.full_name||'Customer')}</h3><div class="address">${icon('pin',11)} ${esc(address(p.opportunities)||'Address not supplied')}</div></div><div class="project-type">${esc(label(p.status))}<br><b>${money(p.scope_estimate)}</b></div></div><div class="project-grid"><div class="project-info"><div class="info-label">Job Type</div><div class="info-value">${esc(p.services?.name||'Service')}</div><div class="person-sub text-clamp">${esc(p.opportunities?.damage_notes||'No scope notes')}</div></div><div class="project-info"><div class="info-label">Schedule</div><div class="info-value">${esc(date(p.opportunities?.preferred_date))}</div><div class="person-sub">${esc(p.opportunities?.preferred_window||'Window not selected')}</div></div><div class="project-action"><span class="tiny">${esc(p.project_members?.[0]?.profiles?.full_name||'Unassigned')}</span>${btn('Open Project','project',p.id,true)}</div></div><div class="project-tags">${tags([p.status,p.billing_type,p.payment_status])}${manages(p)?btn('Refer','refer-project',p.id):''}</div></article>`).join('')}${!r.count?empty('No projects yet. Accept an opportunity or claim a referral to get started.'):pager(r.count)}`;
  }

  async function portal(){const i=await api.rpc('preview_referral',{p_token:params.get('ref')});if(!i)return empty('This invitation is invalid, expired, or revoked.');return head('Project Invitation',i.workspace)+`<section class="panel live-card"><h2>${esc(i.service)}</h2><p>${esc(i.city)} ${esc(i.postal_code)} ${badge(i.priority)}</p><p>Recipient: ${esc(i.invitee_name)}</p><p>${esc(i.special_instructions)}</p><p>Agreed payout ${money(i.payout_amount)} ${badge(i.status)}</p>${s.me&&['viewed','link_sent'].includes(i.status)?btn('Accept this project','claim','',true):!s.me?'<p>Sign in with the invited email address to accept this project.</p>':'<p>This invitation has already been claimed.</p>'}</section>`+(!s.me?auth():'');}
  async function render(){const gen=++s.gen;window.BookingView.unmount();s.route=location.hash.slice(1)||'dashboard';const publicMode=params.has('booking')||params.has('ref');if(!s.me&&!publicMode){location.replace(loginUrl());return;}app.innerHTML=s.me&&!publicMode?shell('<div class="live-loading">Loading…</div>'):'<div class="live-loading">Loading…</div>';try{let html;const [base,id]=s.route.split('/');if(params.has('booking'))html=await booking(params.get('booking'));else if(params.has('ref'))html=await portal();else if(!s.me)html=auth();else if(!s.ws&&s.me.profile.is_platform_admin&&base!=='profile')html=await workspace();else if(!s.me.panels.includes(base==='customer'?'customers':base==='opportunity'?'opportunities':base))html=empty('Select a permitted panel from the menu.');else if(base==='opportunities')html=await opportunities();else if(base==='opportunity')html=await opportunity(id);else if(base==='projects')html=id?await project(id):await projects();else if(base==='quick-referral')html=await referral();else if(base==='customers')html=await customers();else if(base==='customer')html=await customer(id);else if(base==='profile')html=await profile();else if(base==='notifications')html=await notifications();else if(base==='workspace')html=await workspace();else if(base==='user-list')html=await members(false);else if(base==='user-management')html=await userManagement(id);else if(base==='user-tiers')html=await members(true);else if(base==='core-services')html=await services();else if(base==='location')html=await locations();else if(base==='new-service')html=await booking();else html=await dashboard();if(gen!==s.gen)return;app.innerHTML=publicMode?`<main class="public-shell">${html}</main>`:s.me?shell(html):html;const f=app.querySelector('#booking-form');if(f)window.BookingView.mount(f);if(params.has('booking')){const type=app.querySelector('[name="opportunityType"]');if(type){type.value='public';type.closest('label').hidden=true;type.dispatchEvent(new Event('change',{bubbles:true}));}}document.body.classList.remove('menu-open');window.scrollTo(0,0);}catch(e){if(gen!==s.gen)return;const html=empty(e.message)+btn('Retry','retry');app.innerHTML=s.me&&!publicMode?shell(html):html;}}
  function filterUsers(){const term=app.querySelector('[data-user-search]')?.value.trim().toLowerCase()||'',role=app.querySelector('[data-user-role]')?.value||'',status=app.querySelector('[data-user-status]')?.value||'';let visible=0;app.querySelectorAll('[data-user-row]').forEach(row=>{row.hidden=!(row.dataset.search.includes(term)&&(!role||row.dataset.role===role)&&(!status||row.dataset.status===status));if(!row.hidden)visible++;});const count=app.querySelector('[data-user-count]');if(count)count.textContent=`Showing ${visible} workspace members`;}
  app.addEventListener('change',async e=>{try{if(e.target.matches('[data-user-role],[data-user-status]'))filterUsers();if(e.target.name==='contact'){const c=s.cache.contacts[e.target.value];if(c){const f=e.target.form;f.elements.name.value=c.invitee_name;f.elements.email.value=c.invitee_email||'';f.elements.phone.value=c.invitee_phone||'';f.elements.payout_amount.value=c.last_payout||0;}}}catch(e){toast(e.message,true);}});
  app.addEventListener('input',e=>{if(e.target.matches('[data-user-search]'))filterUsers();if(e.target.matches('[data-service-search]')){const term=e.target.value.trim().toLowerCase();app.querySelectorAll('[data-service-card]').forEach(card=>card.hidden=!card.dataset.search.includes(term));}});
  app.addEventListener('click',async e=>{const n=e.target.closest('[data-route]');if(n){go(n.dataset.route);return;}const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;if(action==='target'){const f=b.closest('form');f.elements.target.value=id;f.querySelectorAll('[data-target]').forEach(x=>x.hidden=x.dataset.target!==id);f.querySelectorAll('[data-action="target"]').forEach(x=>x.classList.toggle('active',x===b));return;}if(action==='menu'){app.querySelector('.shell')?.classList.toggle('menu-open');document.body.classList.toggle('menu-open');return;}if(action==='theme'){window.AdminTheme.toggle();return;}if(action==='profile-section'){s.cache.profileSection=s.cache.profileSection===id?null:id;render();return;}if(action==='toggle-member-invite'){s.cache.showInvite=!s.cache.showInvite;render();return;}if(action==='export-users'){const rows=[['Name','Email','Phone','Role','Status'],...(s.cache.people||[]).map(m=>[m.profiles?.full_name||'',m.profiles?.email||'',m.profiles?.phone||'',m.role||'',m.status||''])],csv=rows.map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(',')).join('\\n'),href=URL.createObjectURL(new Blob([csv],{type:'text/csv'})),link=document.createElement('a');link.href=href;link.download='workspace-users.csv';link.click();URL.revokeObjectURL(href);return;}b.disabled=true;try{if(action==='logout'){await api.sb.auth.signOut();s.me=null;s.cache={};render();}else if(action==='retry')render();else if(action==='next'||action==='prev'){s.offset=Math.max(0,s.offset+(action==='next'?25:-25));render();}else if(action==='project')go(`projects/${id}`);else if(action==='opportunity')go(`opportunity/${id}`);else if(action==='customer')go(`customer/${id}`);else if(action==='customer-new')go('customer/new');else if(action==='accept'){const r=await call('opportunities','accept',{id});toast('Opportunity accepted.');go(`projects/${r.project_id}`);}else if(action==='accept-listing'){const r=await call('opportunities','accept_referral',{id});await identity();toast('Referral accepted.');go(`projects/${r.project_id}`);}else if(action==='refer-opportunity'){s.cache.opportunity=id;s.cache.referralProject=null;s.cache.invite=null;go('quick-referral');}else if(action==='refer-project'){s.cache.opportunity=null;s.cache.referralProject=id;s.cache.invite=null;go('quick-referral');}else if(action==='toggle-projects'){s.all=!s.all;s.offset=0;render();}else if(action==='step'){s.step=id;render();}else if(action==='status'){await api.call('my-projects','set_status',{id:s.cache.project.id,status:id});toast('Status updated.');render();}else if(action==='copy-referral'||action==='copy-booking'){await navigator.clipboard.writeText(url(action==='copy-referral'?'ref':'booking',id));toast('Link copied.');}else if(action==='revoke'){await api.call('quick-referral','revoke',{id});toast('Referral revoked.');render();}else if(action==='mark-read'){await call('profile','mark_read');render();}else if(action==='claim'){const r=await call('quick-referral','claim',{token:params.get('ref')});await identity();location.href=location.pathname+`#projects/${r.project_id}`;}}catch(e){toast(e.message,true);}finally{b.disabled=false;}});
  app.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const fd=new FormData(f),data=Object.fromEntries(fd),submit=e.submitter,error=f.querySelector('[data-error]');if(error)error.textContent='';if(submit)submit.disabled=true;try{const kind=f.dataset.form;
    if(kind==='referral'){const activePayout=f.querySelector('[data-target]:not([hidden]) [name="payout_amount"]');if(activePayout)data.payout_amount=activePayout.value;}
    if(kind==='auth'){location.replace('login.html');return;}
    else if(kind==='referral'){const target=data.target,payload={target,payout_amount:Number(data.payout_amount),instructions:data.instructions,name:target==='individual'?data.name:null,email:target==='individual'?data.email||null:null,phone:target==='individual'?data.phone||null:null,target_workspace_id:target==='workspace'?data.target_workspace_id:null};if(target==='individual'&&(!data.name||!data.email&&!data.phone))throw new Error('Enter a contractor name and email or phone.');if(target==='workspace'&&!payload.target_workspace_id)throw new Error('Select a receiving workspace.');s.cache.invite=await call('quick-referral',data.opportunity_id?'refer_opportunity':'create',{...payload,project_id:data.project_id,opportunity_id:data.opportunity_id});s.cache.opportunity=null;toast('Referral created.');render();}
    else if(kind==='search'){s.cache.search=data.search;s.offset=0;render();}
    else if(kind==='customer'){await call('customers','save',{...data,id:f.dataset.id||null});toast('Customer saved.');go('customers');}
    else if(kind==='profile'){await api.call('profile','update',data);await identity();toast('Profile saved.');render();}
    else if(kind==='availability'){await call('profile','set_availability',{days:Array.from({length:7},(_,i)=>({day_of_week:i,available_9_5:!!data[`day-${i}`],available_after_hours:!!data[`after-${i}`]}))});toast('Availability saved.');}
    else if(kind==='workspace'){const r=await api.call('profile','create_workspace',{...data,service_ids:fd.getAll('service_ids')});s.ws=r.id;await identity();toast('Workspace created.');render();}
    else if(kind==='member'){await call('profile','add_member',data);toast('Member added.');render();}
    else if(kind==='member-settings'){await call('profile','member_settings',{user_id:f.dataset.id,role:data.role,status:data.status,available_for_scheduling:!!data.available});await identity();toast('Member updated.');render();}
    else if(kind==='services'){await call('profile','save_services',{service_ids:fd.getAll('service_ids')});toast('Services saved.');render();}
    else if(kind==='location'){await call('profile','save_location',{name:data.name,postal_codes:data.postal_codes.split(',').map(x=>x.trim()).filter(Boolean)});toast('Service area saved.');render();}
    else if(kind==='tiers'){const items=Object.keys(data).filter(k=>k.startsWith('tier-')&&data[k]).map(k=>({service_id:k.slice(5),tier:Number(data[k]),verification_status:data[`verification-${k.slice(5)}`]}));await call('profile','member_services',{user_id:f.dataset.id,items});toast('Tiers saved.');}
    else if(kind==='project-details'){await api.call('my-projects','update',{id:f.dataset.id,scope_estimate:Number(data.scope_estimate),billing_type:data.billing_type,payment_status:data.payment_status});if(data.user_id&&data.user_id!==s.cache.project.assigned_to)await api.call('my-projects','assign',{id:f.dataset.id,user_id:data.user_id});toast('Project details saved.');render();}
    else if(kind==='step'){const previous=s.cache.steps.find(x=>x.step===s.step),payload={...previous.data,...data};delete payload.complete;await api.call('my-projects','save_step',{id:f.dataset.id,step:s.step,data:payload,complete:!!data.complete});toast('Workflow saved.');render();}
  }catch(e){if(error)error.textContent=e.message;else toast(e.message,true);}finally{if(submit)submit.disabled=false;}});
  window.addEventListener('hashchange',()=>{s.offset=0;render();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){app.querySelector('.shell')?.classList.remove('menu-open');document.body.classList.remove('menu-open');}});
  api.sb.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){s.me=null;s.ws=null;s.workspaces=[];s.cache={};location.replace('login.html');}if(event==='TOKEN_REFRESHED')queueMicrotask(()=>identity().catch(e=>toast(e.message,true)));});
  (async()=>{try{const {session}=api.unwrap(await api.sb.auth.getSession());if(session&&!(await identity()))return;if(location.hash.includes('access_token='))history.replaceState(null,'',location.pathname+location.search+'#dashboard');await render();}catch(e){app.innerHTML='<div class="live-loading">Unable to load</div>';toast(e.message,true);}})();
})();
